import java.util.*;

class AuthenticationManager {
    private int ttl;
    private LinkedHashMap<String, Integer> tokens;
    public AuthenticationManager(int timeToLive) {
        this.ttl = timeToLive;
        this.tokens = new LinkedHashMap();
    }
    public void generate(String tokenId, int currentTime) {
        tokens.put(tokenId, currentTime + ttl);
    }
    public void renew(String tokenId, int currentTime) {
        if (tokens.containsKey(tokenId)) {
            int expiry = tokens.get(tokenId).intValue();
            if (expiry > currentTime) {
                tokens.remove(tokenId);
                tokens.put(tokenId, currentTime + ttl);
            }
        }
    }
    public int countUnexpiredTokens(int currentTime) {
        int count = 0;
        Iterator<Map.Entry<String, Integer>> it = tokens.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<String, Integer> entry = it.next();
            if (entry.getValue().intValue() > currentTime) {
                count++;
            }
        }
        return count;
    }
}
